param([string]$Exe, [string]$Props, [string]$Out)
# For every property name in Props (stprops.rs), find where the original program defines it
# (lea rdx,[rip+name] next to lea rcx,[reg+OFF]) and replay the "or/and byte [reg+OFF+0x2c], imm"
# writes that follow, to learn its curve flags (0x02 parent, 0x01 second curve, 0x04 profile).
$b = [IO.File]::ReadAllBytes($Exe)
$pe = [BitConverter]::ToInt32($b, 0x3C)
$nsec = [BitConverter]::ToUInt16($b, $pe + 6)
$optsz = [BitConverter]::ToUInt16($b, $pe + 20)
$sec0 = $pe + 24 + $optsz
$secs = @()
for ($i = 0; $i -lt $nsec; $i++) {
  $o = $sec0 + $i * 40
  $name = [Text.Encoding]::ASCII.GetString($b, $o, 8).Trim([char]0)
  $secs += [pscustomobject]@{ Name = $name; VA = [BitConverter]::ToUInt32($b, $o + 12); Raw = [BitConverter]::ToUInt32($b, $o + 20); Size = [BitConverter]::ToUInt32($b, $o + 16) }
}
$text = $secs | Where-Object Name -eq ".text"
$rdata = $secs | Where-Object Name -eq ".rdata"
$latin = [Text.Encoding]::GetEncoding(28591)
$rs = $latin.GetString($b, [int]$rdata.Raw, [int]$rdata.Size)
$names = [regex]::Matches([IO.File]::ReadAllText($Props), '\(\s*"([^"]+)",') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$rvaToName = @{}
foreach ($n in $names) {
  $needle = [char]0 + $n + [char]0
  $at = 0
  while (($k = $rs.IndexOf($needle, $at, [StringComparison]::Ordinal)) -ge 0) {
    $rvaToName[[int64]($rdata.VA + $k + 1)] = $n
    $at = $k + 1
  }
}
$ts = $latin.GetString($b, [int]$text.Raw, [int]$text.Size)
$pat = [string][char]0x48 + [char]0x8D + [char]0x15
$hits = New-Object System.Collections.Generic.List[object]
$at = 0
while (($k = $ts.IndexOf($pat, $at, [StringComparison]::Ordinal)) -ge 0) {
  $disp = [BitConverter]::ToInt32($b, [int]$text.Raw + $k + 3)
  $target = [int64]$text.VA + $k + 7 + $disp
  if ($rvaToName.ContainsKey($target)) { $hits.Add([pscustomobject]@{ Pos = $k; Name = $rvaToName[$target] }) }
  $at = $k + 1
}
$results = @{}
for ($h = 0; $h -lt $hits.Count; $h++) {
  $pos = $hits[$h].Pos
  $end = if ($h + 1 -lt $hits.Count) { [Math]::Min($hits[$h + 1].Pos, $pos + 900) } else { $pos + 900 }
  # the destination: lea rcx,[reg+disp32] nearest the name (REX 48 or 49, modrm mod=10 reg=001)
  $off = $null; $best = 999
  for ($j = $pos - 40; $j -le $pos + 40; $j++) {
    $p = [int]$text.Raw + $j
    if (($b[$p] -eq 0x48 -or $b[$p] -eq 0x49) -and $b[$p + 1] -eq 0x8D) {
      $m = $b[$p + 2]
      if (($m -band 0xF8) -eq 0x88 -and ($m -band 7) -ne 4) {
        $d = [Math]::Abs($j - $pos)
        if ($d -lt $best) { $best = $d; $off = [BitConverter]::ToInt32($b, $p + 3) }
      }
    }
  }
  if ($null -eq $off) { continue }
  $flagOff = $off + 0x2C
  $flags = 0
  for ($j = $pos; $j -lt $end; $j++) {
    $p = [int]$text.Raw + $j
    $q = $p
    if ($b[$q] -eq 0x41) { $q++ }
    if ($b[$q] -ne 0x80) { continue }
    $m = $b[$q + 1]
    if (($m -band 0xC0) -ne 0x80 -or ($m -band 7) -eq 4) { continue }
    $reg = ($m -shr 3) -band 7
    if ($reg -ne 1 -and $reg -ne 4) { continue }
    if ([BitConverter]::ToInt32($b, $q + 2) -ne $flagOff) { continue }
    $imm = $b[$q + 6]
    if ($reg -eq 1) { $flags = $flags -bor $imm } else { $flags = $flags -band $imm }
  }
  $key = $hits[$h].Name
  if (-not $results.ContainsKey($key)) { $results[$key] = @() }
  $results[$key] += ($flags -band 7)
}
$lines = foreach ($n in ($results.Keys | Sort-Object)) {
  $vals = $results[$n] | Group-Object | Sort-Object Count -Descending
  "{0}`t{1}`t{2}" -f $n, $vals[0].Name, (($results[$n]) -join ',')
}
$lines | Set-Content -Encoding utf8 $Out
"names=$($names.Count) strings=$($rvaToName.Count) hits=$($hits.Count) resolved=$($results.Count)"

