//! Which curves each property has in the original (picture 34). Read from the program's property
//! definitions: each sets a flags byte at the name + 0x5C, where 0x02 = Parent curve (green),
//! 0x01 = a second curve and, with 0x04, that curve is a Profile (yellow, as on Lightmap:Weight,
//! fn 0x14010f240), without it a Distribution (blue, as on Season:Time scale, fn 0x14010ef60).
//! Combined over every generator that defines the property. Generated from the program's
//! machine code; properties not found here fall back to the table's spline flag (Parent only).

pub const CURVE_FLAGS: &[(&str, u8)] = &[
$($rows -join "`n")
];

/// Which curve buttons a property shows: [Parent, Distribution, Profile].
pub fn curve_kinds(name: &str, spline: bool) -> [bool; 3] {
    match CURVE_FLAGS.iter().find(|(n, _)| *n == name) {
        Some((_, f)) => [f & 2 != 0, f & 1 != 0 && f & 4 == 0, f & 1 != 0 && f & 4 != 0],
        None => [spline, false, false],
    }
}
