/// A curve over 0..1: points (x, y) with x rising; y is the multiplier (1 = the value as set).
#[derive(Clone, Debug, PartialEq)]
pub struct Curve {
    pub pts: Vec<Vec2>,
}

impl Curve {
    pub fn flat() -> Self {
        Curve { pts: vec![vec2(0.0, 1.0), vec2(1.0, 1.0)] }
    }
    pub fn eval(&self, x: f32) -> f32 {
        let x = x.clamp(0.0, 1.0);
        match self.pts.as_slice() {
            [] => 1.0,
            [a] => a.y,
            pts => {
                if x <= pts[0].x {
                    return pts[0].y;
                }
                for w in pts.windows(2) {
                    if x <= w[1].x {
                        let f = ((x - w[0].x) / (w[1].x - w[0].x).max(1e-6)).clamp(0.0, 1.0);
                        return w[0].y + (w[1].y - w[0].y) * f;
                    }
                }
                pts[pts.len() - 1].y
            }
        }
    }
}

